const candidateData=<?=json_encode($drawerData,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,rows=[...document.querySelectorAll('[data-candidate]')],search=document.getElementById('filterSearch'),job=document.getElementById('filterJob'),skill=document.getElementById('filterSkill'),experience=document.getElementById('filterExperience'),source=document.getElementById('filterSource'),score=document.getElementById('filterScore'),age=document.getElementById('filterAge'),sort=document.getElementById('filterSort'),count=document.getElementById('filterCount'),empty=document.getElementById('empty'),tableBody=document.querySelector('.candidate-table tbody'),drawer=document.getElementById('candidateDrawer'),shade=document.getElementById('drawerShade');
