const params=new URLSearchParams(location.search);search.value=params.get('q')||'';job.value=params.get('job_id')||'';if(params.get('skill'))skill.value=[...skill.options].find(x=>x.value.toLowerCase()===params.get('skill').toLowerCase())?.value||'';
function filterCandidates(){const terms=search.value.toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);let shown=0;rows.forEach(row=>{const scoreOk=score.value==='0'||(score.value==='analyzed'?row.dataset.analyzed==='1':row.dataset.analyzed==='1'&&+row.dataset.score>=+score.value),ageOk=!age.value||(age.value==='old'?row.dataset.old==='1':row.dataset.old==='0'),visible=(!terms.length||terms.every(term=>row.dataset.find.includes(term)))&&(!job.value||row.dataset.job===job.value)&&(!skill.value||row.dataset.skills.includes('|'+skill.value.toLowerCase()+'|'))&&+row.dataset.months>=+experience.value&&(!source.value||row.dataset.source===source.value)&&scoreOk&&ageOk;row.hidden=!visible;if(visible)shown++});rows.sort((a,b)=>sort.value==='created_desc'?b.dataset.created.localeCompare(a.dataset.created):sort.value==='created_asc'?a.dataset.created.localeCompare(b.dataset.created):sort.value==='experience_desc'?+b.dataset.months-+a.dataset.months:sort.value==='name_asc'?a.dataset.name.localeCompare(b.dataset.name):(+b.dataset.analyzed-+a.dataset.analyzed)||(+b.dataset.score-+a.dataset.score)).forEach(row=>tableBody.appendChild(row));count.textContent=shown+' candidates';empty.hidden=shown!==0}
