function openCandidate(id){const c=candidateData[id];if(!c)return;drawer.dataset.id=id;drawerName.textContent=c.name;drawerRole.textContent=c.job+' · '+c.stage;drawerFlag.innerHTML=c.old?'<span class="old-label"><i class="fa-solid fa-triangle-exclamation"></i> Old application · '+esc(c.age)+'</span>':'Applied '+esc(c.age);gaugeValue.textContent=c.analyzed?c.score+'/100':'Needs analysis';gaugeNeedle.style.setProperty('--needle',(-180+(c.analyzed?c.score:0)*1.8)+'deg');paneOverview.innerHTML='<div class="detail-grid"><div class="detail-card"><small>Stage</small><strong>'+esc(c.stage)+'</strong></div><div class="detail-card"><small>Applied</small><strong>'+esc(c.created_at||'Unknown')+'</strong></div><div class="detail-card"><small>Experience</small><strong>'+(c.months?Math.round(c.months/12*10)/10+' years':'Uncertain')+'</strong></div><div class="detail-card"><small>Source</small><strong>'+esc(c.source)+'</strong></div></div><section class="overview-section"><h3>Employment gaps</h3>'+(c.gaps.length?c.gaps.map(g=>'<p class="old-label">'+Number(g.months||0)+' month gap · '+esc(g.after||'Unknown')+' to '+esc(g.before||'Unknown')+'</p>').join(''):'<p class="muted">No reliable gap of 2+ months detected.</p>')+'</section>';paneEvidence.innerHTML='<h3>Experience-backed requirements</h3>'+chips(c.matched)+'<h3>Needs recruiter review</h3>'+chips(c.review,'extra')+'<h3>Missing requirements</h3>'+chips(c.missing,'missing')+'<h3>Additional preferred skills</h3>'+chips(c.benefits,'extra');const max=Math.max(1,...Object.values(c.skill_months||{}));paneCareer.innerHTML='<section class="overview-section"><h3>Skill-wise experience</h3>'+Object.entries(c.skill_months||{}).map(([name,months])=>'<div class="skill-row"><span>'+esc(name)+'</span><div class="track"><i style="width:'+Math.round(months/max*100)+'%"></i></div><b>'+Math.round(months/12*10)/10+'y</b></div>').join('')+'</section><section class="overview-section"><h3>Employment timeline</h3>'+timeline(c)+'</section>';paneContact.dataset.loaded='';paneContact.innerHTML='<div class="detail-grid"><div class="detail-card"><small>Email</small><strong>'+esc(c.email)+'</strong></div><div class="detail-card"><small>Phone</small><strong>'+esc(c.phone)+'</strong></div><div class="detail-card"><small>Location</small><strong>'+esc(c.country)+'</strong></div><div class="detail-card"><small>Source</small><strong>'+esc(c.source)+'</strong></div></div><section class="overview-section"><h3>Extracted resume text</h3><div class="resume-state">Open Contact tab to load exact extracted text.</div></section>';drawerResume.href=c.resume_url;drawerDetail.href=c.detail_url;drawer.classList.add('open');shade.classList.add('open')}
rows.forEach(row=>{row.addEventListener('click',()=>openCandidate(row.dataset.candidate));row.addEventListener('keydown',e=>{if(e.key==='Enter')openCandidate(row.dataset.candidate)})});function closeDrawer(){drawer.classList.remove('open');shade.classList.remove('open')}drawerClose.onclick=closeDrawer;shade.onclick=closeDrawer;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});document.querySelectorAll('.drawer-tabs button').forEach(button=>button.onclick=()=>{document.querySelectorAll('.drawer-tabs button').forEach(x=>x.classList.toggle('active',x===button));document.querySelectorAll('.tab-pane').forEach(x=>x.classList.toggle('active',x.dataset.pane===button.dataset.tab));if(button.dataset.tab==='contact')loadResumeText()});async function loadResumeText(){const c=candidateData[drawer.dataset.id],pane=paneContact;if(!c||pane.dataset.loaded)return;pane.dataset.loaded='loading';const state=pane.querySelector('.resume-state');state.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Extracting resume text...';try{const response=await fetch(c.text_url,{headers:{Accept:'application/json'}}),payload=await response.json();if(!response.ok||!payload.ok)throw new Error(payload.error||'Text unavailable');state.innerHTML=(payload.warning?'<p class="old-label">'+esc(payload.warning)+'</p>':'')+'<pre class="resume-raw">'+esc(payload.text||'')+'</pre>';pane.dataset.loaded='done'}catch(error){state.textContent=error.message;pane.dataset.loaded=''}}
